package com.twotickskillinghelper;

import lombok.Getter;

/**
 * Follows the 2-tick cycle of an attacker hitting the player and decides, each game tick, whether the player should
 * click their skilling target.
 * <p>
 * Hits normally land every 2 ticks. When PID swaps in PvP, one interval becomes 1 or 3 ticks; the cycle then
 * continues on the opposite tick parity. Clicks are never shown less than {@link #CYCLE_LENGTH} ticks apart, so after
 * a swap the player loses a tick (a 3 tick gap) and is back in cycle with the new PIDs. The lost tick is shown as
 * {@link TickState#SKIP}.
 */
class TickCycleTracker
{
	static final int CYCLE_LENGTH = 2;

	/**
	 * How many ticks the PID swap notice stays up after the swap is detected.
	 */
	private static final int PID_SWAP_NOTICE_TICKS = 3;

	private static final int NONE = Integer.MIN_VALUE;

	private int tick;
	private boolean hitThisTick;
	private int lastHitTick = NONE;
	private int lastClickTick = NONE;
	private int lastSkipTick = NONE;
	private int pidSwapTick = NONE;

	@Getter
	private TickState state = TickState.IDLE;

	/**
	 * Records that the player was hit during the current tick. Call before {@link #onTick}.
	 */
	void hitObserved()
	{
		hitThisTick = true;
	}

	/**
	 * Advances one game tick and recomputes {@link #getState()}.
	 *
	 * @param clickOffset  ticks after a hit on which to click
	 * @param idleTimeout  ticks without a hit before going idle
	 */
	void onTick(int clickOffset, int idleTimeout)
	{
		tick++;

		if (hitThisTick)
		{
			hitThisTick = false;
			if (lastHitTick != NONE && (tick - lastHitTick) % CYCLE_LENGTH != 0)
			{
				pidSwapTick = tick;
			}
			lastHitTick = tick;
		}

		if (lastHitTick == NONE || tick - lastHitTick > idleTimeout)
		{
			state = TickState.IDLE;
			lastHitTick = NONE;
			lastClickTick = NONE;
			lastSkipTick = NONE;
			pidSwapTick = NONE;
			return;
		}

		boolean onClickTick = tick - lastHitTick == clickOffset;
		boolean tooSoon = lastClickTick != NONE && tick - lastClickTick < CYCLE_LENGTH;
		// The regular click is due but there is no hit to click on, e.g. the hit is a tick late after a PID swap
		boolean clickMissed = !onClickTick && lastClickTick != NONE && tick - lastClickTick == CYCLE_LENGTH
			&& lastSkipTick < lastClickTick;

		if (onClickTick && !tooSoon)
		{
			state = TickState.CLICK;
			lastClickTick = tick;
		}
		else if (onClickTick || clickMissed)
		{
			state = TickState.SKIP;
			lastSkipTick = tick;
		}
		else
		{
			state = TickState.WAIT;
		}
	}

	/**
	 * @return whether a PID swap was detected within the last few ticks
	 */
	boolean isPidSwapRecent()
	{
		return pidSwapTick != NONE && tick - pidSwapTick < PID_SWAP_NOTICE_TICKS;
	}

	void reset()
	{
		tick = 0;
		hitThisTick = false;
		lastHitTick = NONE;
		lastClickTick = NONE;
		lastSkipTick = NONE;
		pidSwapTick = NONE;
		state = TickState.IDLE;
	}
}

package com.twotickskillinghelper;

import lombok.Getter;
import lombok.RequiredArgsConstructor;

@RequiredArgsConstructor
@Getter
enum TickState
{
	/**
	 * No attacker hits seen recently; the cycle is unknown.
	 */
	IDLE("IDLE"),
	/**
	 * Click the skilling target this tick.
	 */
	CLICK("CLICK"),
	/**
	 * Off-cycle tick; do nothing.
	 */
	WAIT("WAIT"),
	/**
	 * Would be a click tick, but the cycle is shifting (PID swap), so this click must be skipped to lose a tick.
	 */
	SKIP("SKIP");

	private final String label;
}

package com.twotickskillinghelper;

import java.awt.Color;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Range;

@ConfigGroup("twotickskillinghelper")
public interface TwoTickSkillingHelperConfig extends Config
{
	@ConfigItem(
		keyName = "clickTickOffset",
		name = "Click tick offset",
		description = "Ticks after the attacker's hit lands on which to click.<br>0 = the same tick as the hit, 1 = the tick after",
		position = 0
	)
	@Range(max = 1)
	default int clickTickOffset()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "idleTimeout",
		name = "Idle timeout",
		description = "Ticks without being hit before the indicator goes idle",
		position = 1
	)
	@Range(min = 2, max = 10)
	default int idleTimeout()
	{
		return 4;
	}

	@ConfigItem(
		keyName = "showWhenIdle",
		name = "Show when idle",
		description = "Keep the indicator on screen when no attacker is hitting you",
		position = 2
	)
	default boolean showWhenIdle()
	{
		return true;
	}

	@ConfigItem(
		keyName = "highlightTarget",
		name = "Highlight target",
		description = "Outline the NPC you are skilling on (e.g. the fishing spot) on click ticks",
		position = 3
	)
	default boolean highlightTarget()
	{
		return true;
	}

	@ConfigItem(
		keyName = "clickColor",
		name = "Click color",
		description = "Color shown on ticks where you should click",
		position = 4
	)
	default Color clickColor()
	{
		return new Color(0, 200, 83);
	}

	@ConfigItem(
		keyName = "waitColor",
		name = "Wait color",
		description = "Color shown on off-cycle ticks",
		position = 5
	)
	default Color waitColor()
	{
		return new Color(60, 60, 60);
	}

	@ConfigItem(
		keyName = "skipColor",
		name = "Skip color",
		description = "Color shown when a click must be skipped to lose a tick after a PID swap",
		position = 6
	)
	default Color skipColor()
	{
		return new Color(255, 145, 0);
	}
}

package com.twotickskillinghelper;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * On-screen box telling the player whether to click this tick.
 */
class TwoTickSkillingHelperOverlay extends Overlay
{
	private static final int WIDTH = 110;
	private static final int HEIGHT = 44;
	private static final int NOTICE_HEIGHT = 16;
	private static final Color IDLE_COLOR = new Color(30, 30, 30, 150);
	private static final Font LABEL_FONT = FontManager.getRunescapeBoldFont().deriveFont(28f);
	private static final Font NOTICE_FONT = FontManager.getRunescapeSmallFont();

	private final TwoTickSkillingHelperPlugin plugin;
	private final TwoTickSkillingHelperConfig config;

	@Inject
	TwoTickSkillingHelperOverlay(TwoTickSkillingHelperPlugin plugin, TwoTickSkillingHelperConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		TickState state = plugin.getState();
		if (state == TickState.IDLE && !config.showWhenIdle())
		{
			return null;
		}

		boolean pidSwap = plugin.isPidSwapRecent();
		int height = pidSwap ? HEIGHT + NOTICE_HEIGHT : HEIGHT;

		graphics.setColor(backgroundColor(state));
		graphics.fillRect(0, 0, WIDTH, height);
		graphics.setColor(Color.BLACK);
		graphics.drawRect(0, 0, WIDTH - 1, height - 1);

		graphics.setFont(LABEL_FONT);
		drawCentered(graphics, state.getLabel(), HEIGHT, 0, state == TickState.IDLE ? Color.GRAY : Color.WHITE);

		if (pidSwap)
		{
			graphics.setFont(NOTICE_FONT);
			drawCentered(graphics, "PID swap", NOTICE_HEIGHT, HEIGHT - 4, Color.WHITE);
		}

		return new Dimension(WIDTH, height);
	}

	private Color backgroundColor(TickState state)
	{
		switch (state)
		{
			case CLICK:
				return config.clickColor();
			case WAIT:
				return config.waitColor();
			case SKIP:
				return config.skipColor();
			default:
				return IDLE_COLOR;
		}
	}

	private static void drawCentered(Graphics2D graphics, String text, int boxHeight, int top, Color color)
	{
		FontMetrics metrics = graphics.getFontMetrics();
		int x = (WIDTH - metrics.stringWidth(text)) / 2;
		int y = top + (boxHeight - metrics.getHeight()) / 2 + metrics.getAscent();

		graphics.setColor(Color.BLACK);
		graphics.drawString(text, x + 1, y + 1);
		graphics.setColor(color);
		graphics.drawString(text, x, y);
	}
}

package com.twotickskillinghelper;

import com.google.common.collect.ImmutableSet;
import com.google.inject.Provides;
import java.util.Set;
import javax.inject.Inject;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Actor;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.HitsplatID;
import net.runelite.api.NPC;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.HitsplatApplied;
import net.runelite.api.events.InteractingChanged;
import net.runelite.api.events.NpcDespawned;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

@Slf4j
@PluginDescriptor(
	name = "2 Tick Skilling Helper",
	description = "Helps with 2-tick skilling methods",
	tags = {"tick", "2t", "skilling", "tick manipulation", "fishing"}
)
public class TwoTickSkillingHelperPlugin extends Plugin
{
	/**
	 * Hitsplats caused by an attack (including blocked 0s). Poison, venom, heals etc. tick on their own timers and
	 * would break the cycle.
	 */
	private static final Set<Integer> ATTACK_HITSPLATS = ImmutableSet.of(
		HitsplatID.BLOCK_ME, HitsplatID.BLOCK_OTHER,
		HitsplatID.DAMAGE_ME, HitsplatID.DAMAGE_OTHER,
		HitsplatID.DAMAGE_ME_CYAN, HitsplatID.DAMAGE_OTHER_CYAN,
		HitsplatID.DAMAGE_ME_ORANGE, HitsplatID.DAMAGE_OTHER_ORANGE,
		HitsplatID.DAMAGE_ME_YELLOW, HitsplatID.DAMAGE_OTHER_YELLOW,
		HitsplatID.DAMAGE_ME_WHITE, HitsplatID.DAMAGE_OTHER_WHITE,
		HitsplatID.DAMAGE_MAX_ME, HitsplatID.DAMAGE_MAX_ME_CYAN, HitsplatID.DAMAGE_MAX_ME_ORANGE,
		HitsplatID.DAMAGE_MAX_ME_YELLOW, HitsplatID.DAMAGE_MAX_ME_WHITE,
		HitsplatID.DAMAGE_ME_POISE, HitsplatID.DAMAGE_OTHER_POISE, HitsplatID.DAMAGE_MAX_ME_POISE
	);

	@Inject private Client client;
	@Inject private TwoTickSkillingHelperConfig config;
	@Inject private OverlayManager overlayManager;
	@Inject private TwoTickSkillingHelperOverlay overlay;
	@Inject private TwoTickSkillingHelperTargetOverlay targetOverlay;

	private final TickCycleTracker tracker = new TickCycleTracker();

	/**
	 * The NPC the player is skilling on, e.g. the fishing spot.
	 */
	@Getter
	private NPC target;

	@Override
	protected void startUp()
	{
		overlayManager.add(overlay);
		overlayManager.add(targetOverlay);
	}

	@Override
	protected void shutDown()
	{
		overlayManager.remove(overlay);
		overlayManager.remove(targetOverlay);
		tracker.reset();
		target = null;
	}

	TickState getState()
	{
		return tracker.getState();
	}

	boolean isPidSwapRecent()
	{
		return tracker.isPidSwapRecent();
	}

	@Subscribe
	public void onHitsplatApplied(HitsplatApplied event)
	{
		if (event.getActor() == client.getLocalPlayer()
			&& ATTACK_HITSPLATS.contains(event.getHitsplat().getHitsplatType()))
		{
			tracker.hitObserved();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		tracker.onTick(config.clickTickOffset(), config.idleTimeout());
	}

	@Subscribe
	public void onInteractingChanged(InteractingChanged event)
	{
		Actor localPlayer = client.getLocalPlayer();
		if (event.getSource() != localPlayer || !(event.getTarget() instanceof NPC))
		{
			return;
		}

		NPC npc = (NPC) event.getTarget();
		// Don't treat the attacker as the skilling target if the player retaliates
		if (npc.getInteracting() != localPlayer)
		{
			target = npc;
		}
	}

	@Subscribe
	public void onNpcDespawned(NpcDespawned event)
	{
		if (event.getNpc() == target)
		{
			target = null;
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOGIN_SCREEN || event.getGameState() == GameState.HOPPING)
		{
			tracker.reset();
			target = null;
		}
	}

	@Provides
	TwoTickSkillingHelperConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(TwoTickSkillingHelperConfig.class);
	}
}

package com.twotickskillinghelper;

import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.NPC;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;

/**
 * Outlines the skilling target (e.g. the fishing spot) on click ticks.
 */
class TwoTickSkillingHelperTargetOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 3;
	private static final int OUTLINE_FEATHER = 4;

	private final TwoTickSkillingHelperPlugin plugin;
	private final TwoTickSkillingHelperConfig config;
	private final ModelOutlineRenderer modelOutlineRenderer;

	@Inject
	TwoTickSkillingHelperTargetOverlay(TwoTickSkillingHelperPlugin plugin, TwoTickSkillingHelperConfig config,
		ModelOutlineRenderer modelOutlineRenderer)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		this.modelOutlineRenderer = modelOutlineRenderer;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		NPC target = plugin.getTarget();
		if (!config.highlightTarget() || target == null || plugin.getState() != TickState.CLICK)
		{
			return null;
		}

		modelOutlineRenderer.drawOutline(target, OUTLINE_WIDTH, config.clickColor(), OUTLINE_FEATHER);
		return null;
	}
}

package com.twotickskillinghelper;

import static com.twotickskillinghelper.TickState.CLICK;
import static com.twotickskillinghelper.TickState.IDLE;
import static com.twotickskillinghelper.TickState.SKIP;
import static com.twotickskillinghelper.TickState.WAIT;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Before;
import org.junit.Test;

public class TickCycleTrackerTest
{
	private static final int IDLE_TIMEOUT = 4;

	private TickCycleTracker tracker;

	@Before
	public void setUp()
	{
		tracker = new TickCycleTracker();
	}

	/**
	 * Runs one tick per character: 'x' = hit that tick, '.' = no hit.
	 */
	private TickState[] run(String hits, int clickOffset)
	{
		TickState[] states = new TickState[hits.length()];
		for (int i = 0; i < hits.length(); i++)
		{
			if (hits.charAt(i) == 'x')
			{
				tracker.hitObserved();
			}
			tracker.onTick(clickOffset, IDLE_TIMEOUT);
			states[i] = tracker.getState();
		}
		return states;
	}

	@Test
	public void steadyCycleClicksOnHitTicks()
	{
		assertArrayEquals(
			new TickState[]{IDLE, CLICK, WAIT, CLICK, WAIT, CLICK, WAIT},
			run(".x.x.x.", 0));
		assertFalse(tracker.isPidSwapRecent());
	}

	@Test
	public void steadyCycleWithOffsetClicksTickAfterHit()
	{
		assertArrayEquals(
			new TickState[]{WAIT, CLICK, WAIT, CLICK, WAIT, CLICK},
			run("x.x.x.", 1));
	}

	@Test
	public void earlyPidSwapSkipsOneClick()
	{
		// Hits at 0, 2, then 3 (1 tick early), then every 2 from there
		assertArrayEquals(
			new TickState[]{CLICK, WAIT, CLICK, SKIP, WAIT, CLICK, WAIT, CLICK},
			run("x.xx.x.x", 0));
	}

	@Test
	public void latePidSwapLosesATick()
	{
		// Hits at 0, 2, then 5 (1 tick late), then every 2 from there
		assertArrayEquals(
			new TickState[]{CLICK, WAIT, CLICK, WAIT, SKIP, CLICK, WAIT, CLICK},
			run("x.x..x.x", 0));
	}

	@Test
	public void latePidSwapWithOffsetLosesATick()
	{
		assertArrayEquals(
			new TickState[]{WAIT, CLICK, WAIT, CLICK, WAIT, SKIP, CLICK, WAIT},
			run("x.x..x.x", 1));
	}

	@Test
	public void earlyPidSwapWithOffsetLosesATick()
	{
		assertArrayEquals(
			new TickState[]{WAIT, CLICK, WAIT, SKIP, CLICK, WAIT, CLICK, WAIT},
			run("x.xx.x.x", 1));
	}

	@Test
	public void pidSwapNoticeShownAfterSwap()
	{
		run("x.xx", 0);
		assertTrue(tracker.isPidSwapRecent());
		run("...", 0);
		assertFalse(tracker.isPidSwapRecent());
	}

	@Test
	public void goesIdleAfterTimeout()
	{
		assertArrayEquals(
			new TickState[]{CLICK, WAIT, SKIP, WAIT, WAIT, IDLE},
			run("x.....", 0));
	}

	@Test
	public void resumesAfterIdleWithoutSkipping()
	{
		run("x......", 0);
		assertArrayEquals(new TickState[]{CLICK, WAIT, CLICK}, run("x.x", 0));
		assertFalse(tracker.isPidSwapRecent());
	}
}

package com.twotickskillinghelper;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class TwoTickSkillingHelperPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(TwoTickSkillingHelperPlugin.class);
		RuneLite.main(args);
	}
}
